mapper.select:
SELECT T.* FROM (SELECT O.*, F.PROCESSSTATUS FOLDERSTATUS, F.MONITORPOINTNAME, F.MONITORPOINTNO, P.PROJNO, P.PROJNAME, P.SAMPLE, F.FOLDERNO, F.SAMPLEUSERID, F.SAMPLEUSERNAME, S.ACCEPTEDTIME
,K.TESTNAME, K.EQUIPTID, K.EQUIPTNAME, K.RUNID
FROM T_EMC_ORDER O LEFT JOIN T_EMC_FOLDER F ON F.ID = O.FOLDERID LEFT JOIN T_EMC_PROJECT P ON P.ID = O.PROJID LEFT JOIN T_EMC_SAMPLE S ON O.SAMPLEID = S.ID
LEFT JOIN (SELECT B.ORDERID, B.RUNID, WM_CONCAT(DISTINCT B.TESTNAME) AS TESTNAME, WM_CONCAT(DISTINCT C.EQUIPTID) AS EQUIPTID, WM_CONCAT(DISTINCT C.EQUIPTNAME) AS EQUIPTNAME FROM T_EMC_ORDER_TASK B LEFT JOIN T_EMC_EQUIPT C ON B.EQUIPTID = C.ID WHERE B.RUNID IN (SELECT REGEXP_SUBSTR(#{relatedRunId}, '[^,]+', 1, LEVEL, 'i') AS STR FROM DUAL CONNECT BY REGEXP_SUBSTR(#{relatedRunId}, '[^,]+', 1, LEVEL, 'i') IS NOT NULL) GROUP BY B.ORDERID,B.RUNID) K ON O.ID = K.ORDERID
) T
AND EXISTS (SELECT 1 FROM ${targetSampleTable} TAR_ WHERE TAR_.${targetSampleIdColumn} = T.${targetSampleIdColumn}
AND TAR_.${targetSampleCategoryFilterColumn} = #{targetSampleCategoryFilterValue}
AND TAR_.${targetFilterColumn1} = #{targetFilterValue1}
)
AND EXISTS (SELECT 1 FROM ${targetTable} TAR_ WHERE TAR_.${targetColumn} = T.ID
AND TAR_.${targetFilterColumn1} = #{targetFilterValue1}
AND TAR_.${targetFilterColumn2} = #{targetFilterValue2}
)
AND NOT EXISTS (SELECT 1 FROM ${targetOrderTable} TAR_ WHERE TAR_.${targetOrderColumn} = T.ID
AND TAR_.${targetOrderIdFilterColumn} = #{targetOrderIdFilterValue}
AND TAR_.${targetFilterColumn1} = #{targetFilterValue1}
)
AND NOT EXISTS (SELECT 1 FROM T_EMC_ORDER TAR_ WHERE TAR_.ID = T.ID AND TAR_.SAMPLEID IS NOT NULL)
AND ( T.SAMPLEID IS NULL OR T.SAMPLEID = '')
AND EXISTS (SELECT 1 FROM T_EMC_FOLDER F WHERE T.FOLDERID = F.ID AND F.PROCESSSTATUS = 'done' AND (INSTR( ',' || SAMPLEUSERID || ',',',' || #{sampleUserId} || ',' ) > 0 OR INSTR(',' || SCENEUSERID || ',',',' || #{sceneUserId} || ',' ) > 0) OR INSTR( ',' || PLANSAMPLEUSERID || ',',',' || #{sampleUserId} || ',' ) > 0)
AND EXISTS (SELECT 1 FROM T_EMC_ORDER_TASK K WHERE K.ORDERID = T.ID AND K.RUNID IN (SELECT REGEXP_SUBSTR(#{relatedRunId}, '[^,]+', 1, LEVEL, 'i') AS STR FROM DUAL CONNECT BY REGEXP_SUBSTR(#{relatedRunId}, '[^,]+', 1, LEVEL, 'i') IS NOT NULL) ) AND ID NOT IN (SELECT RELATEDORDERID FROM T_EMC_QC_RELATED_ORDER R WHERE R.QCORDERID = #{id} AND R.TASKRUNID = T.RUNID)
AND EXISTS (SELECT 1 FROM T_EMC_ORDER_TASK K WHERE K.ORDERID = T.ID AND K.STATUS = 'logged' AND K.ANALYSISTYPE = 'analysis' AND K.RUNID IS NULL AND K.TESTMETHODID IN (#{testMethodId}))
ORDER BY
T.FOLDERID ASC, T.ORDERNO ASC, T.ID DESC

SELECT T.*
  FROM T_EMC_ORDER T
 WHERE T.ID = #{id}
